/* Study site — single-file hash-routed app. Data comes from data.js (generated by build/parse.py). */
(function () {
  'use strict';
  const D = Object.assign({}, window.STUDY_META, { courses: (window.STUDY_COURSES || []).slice().sort((a, b) => a.order - b.order) });
  const app = document.getElementById('app');
  const byId = Object.fromEntries(D.courses.map(c => [c.id, c]));

  // ------------------------------------------------------------------ storage
  const store = {
    get(key, fallback) { try { const v = localStorage.getItem(key); return v ? JSON.parse(v) : fallback; } catch (e) { return fallback; } },
    set(key, val) { try { localStorage.setItem(key, JSON.stringify(val)); } catch (e) { /* ignore */ } },
  };
  const readState = () => store.get('study.read', {});
  const isRead = (cid, slug) => !!(readState()[cid] || {})[slug];
  const setRead = (cid, slug, on) => { const s = readState(); s[cid] = s[cid] || {}; if (on) s[cid][slug] = 1; else delete s[cid][slug]; store.set('study.read', s); };
  const courseProgress = (c) => { const s = readState()[c.id] || {}; const total = c.units.length; const done = c.units.filter(u => s[u.slug]).length; return { done, total, pct: total ? Math.round(done / total * 100) : 0 }; };
  const cardState = () => store.get('study.cards', {});
  const setCard = (key, v) => { const s = cardState(); if (v) s[key] = v; else delete s[key]; store.set('study.cards', s); };

  // ------------------------------------------------------------------ helpers
  const esc = (s) => String(s).replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
  // pitfall/reminder paragraphs of a unit (flagged by the parser) — used for badges and the collapsible list
  const calloutsOfBlocks = (blocks) => (blocks || []).flatMap(b => b.type === 'p' && b.callout ? [b.html] : b.type === 'list' ? b.items.filter(it => it.callout).map(it => it.html) : []);
  const calloutsOf = (u) => calloutsOfBlocks(u.blocks).concat(...u.subunits.map(s => calloutsOfBlocks(s.blocks)));
  const chip = (text, cls = '') => `<span class="chip ${cls}">${text}</span>`;
  const courseChip = (cid) => { const c = byId[cid]; return c ? chip(esc(c.short), c.track) : ''; };

  function renderBlocks(blocks) {
    return (blocks || []).map(b => {
      switch (b.type) {
        case 'p': return `<p class="${b.callout ? 'callout' : ''}">${b.html}</p>`;
        case 'quote': return `<div class="quote"><p>${b.html}</p></div>`;
        case 'code': return `<pre><code class="lang-${esc(b.lang || '')}">${esc(b.text)}</code></pre>`;
        case 'hr': return '<hr>';
        case 'table': return renderTable(b.headers, b.rows, 'md');
        case 'list': {
          const tag = b.ordered ? 'ol' : 'ul';
          const items = b.items.map(it => `<li class="${it.callout ? 'callout' : ''}"><div class="li-text">${it.html}</div>${it.children ? renderBlocks(it.children) : ''}</li>`).join('');
          return `<${tag}>${items}</${tag}>`;
        }
        default: return '';
      }
    }).join('');
  }

  function renderTable(headers, rows, cls) {
    return `<div class="table-wrap"><table class="${cls}"><thead><tr>${headers.map(h => `<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r => `<tr>${r.map(c => `<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  }

  function setActiveNav(route) {
    document.querySelectorAll('#nav a').forEach(a => a.classList.toggle('active', a.dataset.route === route));
  }

  // ------------------------------------------------------------------ views: home
  function viewHome() {
    setActiveNav('home');
    const totalUnits = D.courses.reduce((n, c) => n + c.units.length, 0);
    const doneUnits = D.courses.reduce((n, c) => n + courseProgress(c).done, 0);
    const totalMin = D.courses.reduce((n, c) => n + c.read_minutes, 0);
    const cs = cardState();
    const known = Object.values(cs).filter(v => v === 'known').length;

    const pathHtml = D.paths.map(p => {
      const steps = p.steps.map((s, i) => {
        if (s.course === 'core') {
          const devCourses = D.courses.filter(c => c.platform);
          return `<div class="step"><div class="num">${i + 1}</div>
            <a class="card course-card" href="#/core">
              <div class="title-row"><h3>核心合併視圖：Claude 開發課（三平台）</h3>${chip('11 個主題', 'dev')}</div>
              <div class="meta"><span>合併 ${devCourses.map(c => esc(c.short)).join('、')}</span><span>三份共約 ${devCourses.reduce((n, c) => n + c.read_minutes, 0)} 分鐘，合併後只讀一次</span></div>
              <p class="note">${esc(s.note)}</p>
            </a></div>`;
        }
        const c = byId[s.course];
        const pr = courseProgress(c);
        return `<div class="step"><div class="num">${i + 1}</div>
          <a class="card course-card" href="#/course/${c.id}">
            <div class="title-row"><h3>${esc(c.title)}</h3>${chip(esc(c.audience))}${pr.done ? chip(`${pr.done}/${pr.total} 已讀`, 'ok') : ''}</div>
            <div class="meta"><span>${esc(c.tagline)}</span><span>${c.units.length} 個單元</span><span>約 ${c.read_minutes} 分鐘</span><span>${c.callout_count} 個陷阱提示</span></div>
            <div class="progress"><span style="width:${pr.pct}%"></span></div>
            <p class="note">${esc(s.note)}</p>
          </a></div>`;
      }).join('');
      return `<section class="path ${p.id}"><div class="path-head"><h2>${esc(p.title)}</h2><span class="muted">${esc(p.desc)}</span></div><div class="steps">${steps}</div></section>`;
    }).join('');

    const platformCourses = D.courses.filter(c => c.platform);
    app.innerHTML = `
      <div class="hero">
        <h1>七門課、兩條軌、一次讀懂</h1>
        <p class="lead">把七份課程導讀拆成結構化資料：先看學習路徑，開發者三份平台課用合併視圖只讀一次，再用卡片把易搞混的觀念與數字練熟。</p>
        <div class="stats">
          <span><b>${D.courses.length}</b>門課</span>
          <span><b>${totalUnits}</b>個單元</span>
          <span><b>${totalMin}</b>分鐘原始閱讀量</span>
          <span><b>${D.cards.length}</b>張卡片</span>
          <span><b>${D.glossary.length}</b>個術語</span>
          <span><b>${doneUnits}</b>/${totalUnits} 單元已讀</span>
          <span><b>${known}</b>張卡片已熟</span>
        </div>
      </div>
      ${pathHtml}
      <section class="tools">
        <h2>學習工具</h2>
        <div class="grid cols-3">
          <a class="card tool" href="#/core"><div class="big">3 → 1</div><h3>核心合併視圖</h3><p class="muted small">${platformCourses.map(c => esc(c.short)).join(' / ')} 三份同一門課的平台版本。每個主題先看共通核心，再看差異表，原文用分頁切換。</p></a>
          <a class="card tool" href="#/cards"><div class="big">${D.cards.length}</div><h3>易搞混與數字卡</h3><p class="muted small">正面是問題，點一下翻面看答案。標記熟或不熟，可只練不熟的。</p></a>
          <a class="card tool" href="#/glossary"><div class="big">${D.glossary.length}</div><h3>術語表</h3><p class="muted small">從導讀裡「專有名詞（中文解釋）」的寫法自動抽出，附出現在哪幾門課。</p></a>
        </div>
      </section>`;
  }

  // ------------------------------------------------------------------ views: course
  function viewCourse(cid) {
    const c = byId[cid];
    if (!c) { app.innerHTML = '<div class="empty">找不到這門課。</div>'; return; }
    setActiveNav(null);
    const pr = courseProgress(c);

    const keyGroups = c.key_groups.map(g => `<div class="keygroup">${g.title ? `<h3>${g.title_html}</h3>` : ''}${renderBlocks(g.blocks)}</div>`).join('');

    const units = c.units.map((u, i) => {
      const done = isRead(c.id, u.slug);
      const subs = u.subunits.map(s => `<div class="subunit" id="${s.slug}"><h4>${s.title_html}</h4>${renderBlocks(s.blocks)}</div>`).join('');
      const callouts = calloutsOf(u);
      const pit = callouts.length ? `<details class="pitfalls"><summary>本單元的 ${callouts.length} 個陷阱與提醒</summary><ul>${callouts.map(x => `<li>${x}</li>`).join('')}</ul></details>` : '';
      return `<details class="unit ${done ? 'done' : ''}" id="${u.slug}" data-slug="${u.slug}">
        <summary>
          <span class="caret">▶</span>
          <span><div class="ut">${u.title_html}</div>${u.summary ? `<div class="us">${esc(u.summary)}</div>` : ''}</span>
          <span class="badges">${callouts.length ? chip(`${callouts.length} 提醒`, 'warn') : ''}<label class="readbox" onclick="event.stopPropagation()"><input type="checkbox" data-read="${u.slug}" ${done ? 'checked' : ''}> 已讀</label></span>
        </summary>
        <div class="body">${pit}${renderBlocks(u.blocks)}${subs}</div>
      </details>`;
    }).join('');

    const toc = `<nav class="toc">
      <div class="toc-h">目錄</div>
      <a href="#intro">這門課在講什麼</a>
      ${c.key_groups.length ? '<a href="#keys">先記住的表</a>' : ''}
      <div class="toc-h">各單元</div>
      ${c.units.map(u => `<a href="#${u.slug}" class="${isRead(c.id, u.slug) ? 'done' : ''}" data-toc="${u.slug}">${esc(u.title)}</a>`).join('')}
      <a href="#takeaways">學完得到什麼</a>
    </nav>`;

    app.innerHTML = `
      <a class="back" href="#/">← 回首頁</a>
      <div class="course-layout">
        <article>
          <header class="course-head">
            <div>${chip(c.track === 'dev' ? '開發者軌' : '非技術軌', c.track)} ${chip(esc(c.audience))}</div>
            <h1>${esc(c.title)}</h1>
            <p class="lead">${esc(c.tagline)}</p>
            <div class="meta"><span>${c.units.length} 個單元</span><span>約 ${c.read_minutes} 分鐘</span><span>${c.callout_count} 個陷阱提示</span><span id="prog-text">${pr.done}/${pr.total} 已讀</span></div>
            <div class="progress"><span id="prog-bar" style="width:${pr.pct}%"></span></div>
            ${c.head_meta.length ? `<div class="headmeta">${c.head_meta.map(m => `<p>${m}</p>`).join('')}</div>` : ''}
          </header>

          <h2 id="intro">這門課在講什麼</h2>
          ${renderBlocks(c.intro)}

          ${c.key_groups.length ? `<h2 id="keys">${esc(c.keys_title || '先記住這幾張表')}</h2>${keyGroups}` : ''}

          <div class="section-title"><h2 id="units">各單元內容導讀</h2>
            <div class="actions"><button class="chip btn" id="expand-all">全部展開</button><button class="chip btn" id="collapse-all">全部收合</button></div></div>
          <p class="muted small">點標題展開。勾「已讀」會記在這個瀏覽器裡。黃色框是文件中標記為易搞混、陷阱、注意的段落。</p>
          ${units}

          <h2 id="takeaways">讀完這門課你會得到什麼</h2>
          ${renderBlocks(c.takeaways)}
          ${c.footer ? `<hr><p class="muted small">${c.footer}</p>` : ''}
        </article>
        ${toc}
      </div>`;

    app.querySelectorAll('input[data-read]').forEach(cb => cb.addEventListener('change', () => {
      setRead(c.id, cb.dataset.read, cb.checked);
      const det = cb.closest('.unit'); det.classList.toggle('done', cb.checked);
      const t = app.querySelector(`[data-toc="${cb.dataset.read}"]`); if (t) t.classList.toggle('done', cb.checked);
      const p2 = courseProgress(c);
      document.getElementById('prog-text').textContent = `${p2.done}/${p2.total} 已讀`;
      document.getElementById('prog-bar').style.width = p2.pct + '%';
    }));
    document.getElementById('expand-all').onclick = () => app.querySelectorAll('.unit').forEach(d => d.open = true);
    document.getElementById('collapse-all').onclick = () => app.querySelectorAll('.unit').forEach(d => d.open = false);
    // in-page anchors: open the target unit before scrolling
    app.querySelectorAll('.toc a[href^="#"]').forEach(a => a.addEventListener('click', (e) => {
      e.preventDefault();
      const id = a.getAttribute('href').slice(1);
      const el = document.getElementById(id);
      if (!el) return;
      const det = el.closest('.unit') || el; if (det.tagName === 'DETAILS') det.open = true;
      el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }));
    // open first unit by default so the page does not look empty
    const first = app.querySelector('.unit'); if (first) first.open = true;
  }

  // ------------------------------------------------------------------ views: core merged
  function viewCore(topicId) {
    setActiveNav('core');
    const topics = D.core_topics;
    const t = topics.find(x => x.id === topicId) || topics[0];
    const idx = topics.indexOf(t);
    const platforms = Object.entries(D.platforms); // [key, {label, course}]
    let plat = store.get('study.platform', 'api');
    if (!D.platforms[plat]) plat = 'api';

    const nav = `<nav class="topic-nav">${topics.map(x => `<a href="#/core/${x.id}" class="${x.id === t.id ? 'active' : ''}"><span class="n">${x.n}</span><span class="t">${esc(x.title)}</span></a>`).join('')}</nav>`;

    const diffs = t.diffs && t.diffs.length ? renderTable(['面向', ...platforms.map(([, p]) => esc(p.label))],
      t.diffs.map(d => [esc(d.aspect), ...platforms.map(([k]) => { const v = d[k] || '—'; return /^與 API 相同/.test(v) || v === '—' ? `<span class="same">${v}</span>` : v; })]), 'md diff') : '<p class="muted">這個主題三個平台的內容一致，沒有需要另記的差異。</p>';

    const unitsFor = (pk) => { const cid = D.platforms[pk].course; const c = byId[cid]; return (t.units[cid] || []).map(i => c.units[i]).filter(Boolean).map(u => ({ course: c, unit: u })); };

    const renderPlatformBody = (pk) => unitsFor(pk).map(({ course, unit }) => `
      <div class="card" style="margin-bottom:14px">
        <div class="muted small">${esc(course.title)} · <a href="#/course/${course.id}#${unit.slug}">在課程頁開啟</a></div>
        <h3 style="margin-top:4px">${unit.title_html}</h3>
        ${calloutsOf(unit).length ? `<details class="pitfalls"><summary>${calloutsOf(unit).length} 個陷阱與提醒</summary><ul>${calloutsOf(unit).map(x => `<li>${x}</li>`).join('')}</ul></details>` : ''}
        ${renderBlocks(unit.blocks)}
        ${unit.subunits.map(s => `<div class="subunit"><h4>${s.title_html}</h4>${renderBlocks(s.blocks)}</div>`).join('')}
      </div>`).join('') || '<p class="muted">這個平台的導讀沒有對應單元。</p>';

    app.innerHTML = `
      <div class="core-layout">
        ${nav}
        <article>
          <header class="topic-head">
            <div>${chip('核心合併視圖', 'dev')} ${chip(`主題 ${t.n} / ${topics.length}`)}</div>
            <h1>${esc(t.title)}</h1>
            <p class="one">${esc(t.one_line)}</p>
          </header>

          <h2>共通核心（三平台都一樣）</h2>
          <ul class="common">${t.common.map(x => `<li>${x}</li>`).join('')}</ul>

          <h2>平台差異</h2>
          ${t.note ? `<div class="diff-note">${esc(t.note)}</div>` : ''}
          ${diffs}

          <h2>完整原文</h2>
          <p class="muted small">選一個平台看該份導讀的原文。你的選擇會被記住。</p>
          <div class="tabs" id="plat-tabs">${platforms.map(([k, p]) => `<button data-plat="${k}" class="${k === plat ? 'active' : ''}">${esc(p.label)}</button>`).join('')}</div>
          <div id="plat-body">${renderPlatformBody(plat)}</div>

          <div class="pager">
            ${idx > 0 ? `<a href="#/core/${topics[idx - 1].id}">← ${esc(topics[idx - 1].title)}</a>` : '<span></span>'}
            ${idx < topics.length - 1 ? `<a href="#/core/${topics[idx + 1].id}">${esc(topics[idx + 1].title)} →</a>` : '<span></span>'}
          </div>
        </article>
      </div>`;

    document.getElementById('plat-tabs').addEventListener('click', (e) => {
      const b = e.target.closest('button[data-plat]'); if (!b) return;
      plat = b.dataset.plat; store.set('study.platform', plat);
      document.querySelectorAll('#plat-tabs button').forEach(x => x.classList.toggle('active', x === b));
      document.getElementById('plat-body').innerHTML = renderPlatformBody(plat);
    });
  }

  // ------------------------------------------------------------------ views: cards
  const cardKey = (card) => card.deck + '|' + card.q;
  function viewCards() {
    setActiveNav('cards');
    const ui = store.get('study.cards.ui', { deck: 'confuse', course: 'all', onlyUnknown: false, shuffle: false });
    const decks = [['confuse', '易搞混'], ['numbers', '數字速記']];
    const courseIds = D.courses.map(c => c.id);

    function render() {
      const st = cardState();
      let cards = D.cards.filter(c => c.deck === ui.deck);
      if (ui.course !== 'all') cards = cards.filter(c => c.courses.includes(ui.course));
      if (ui.onlyUnknown) cards = cards.filter(c => st[cardKey(c)] !== 'known');
      if (ui.shuffle) cards = cards.map(c => [Math.random(), c]).sort((a, b) => a[0] - b[0]).map(x => x[1]);
      const deckAll = D.cards.filter(c => c.deck === ui.deck);
      const knownCount = deckAll.filter(c => st[cardKey(c)] === 'known').length;

      app.innerHTML = `
        <h1>卡片練習</h1>
        <p class="lead">正面是問題，先想答案再點卡片翻面。翻面後標記「熟了」或「還不熟」，之後可只練不熟的。</p>
        <div class="toolbar">
          ${decks.map(([k, label]) => `<button class="chip btn ${ui.deck === k ? 'on' : ''}" data-deck="${k}">${label} ${D.cards.filter(c => c.deck === k).length}</button>`).join('')}
          <span class="sep"></span>
          <button class="chip btn ${ui.course === 'all' ? 'on' : ''}" data-course="all">全部課程</button>
          ${courseIds.map(id => `<button class="chip btn ${ui.course === id ? 'on' : ''}" data-course="${id}">${esc(byId[id].short)}</button>`).join('')}
          <span class="sep"></span>
          <button class="chip btn ${ui.onlyUnknown ? 'on' : ''}" data-toggle="onlyUnknown">只看不熟</button>
          <button class="chip btn ${ui.shuffle ? 'on' : ''}" data-toggle="shuffle">隨機排序</button>
          <button class="chip btn" data-reset="1">重設此組標記</button>
        </div>
        <p class="muted small">這組 ${deckAll.length} 張，已熟 ${knownCount} 張；目前顯示 ${cards.length} 張。</p>
        <div class="deck-grid">${cards.map((c, i) => {
          const s = st[cardKey(c)] || '';
          return `<div class="fc ${s}" data-i="${i}">
            <div class="fc-inner">
              <div class="fc-face front"><div class="q">${esc(c.q)}</div><div class="foot">${c.courses.map(courseChip).join('')}<span class="hint">${s === 'known' ? '已熟' : s === 'unknown' ? '還不熟' : '點一下翻面'}</span></div></div>
              <div class="fc-face back"><div class="a">${esc(c.a)}</div>
                <div class="mark"><button class="ok" data-mark="known">熟了 ✓</button><button class="no" data-mark="unknown">還不熟</button></div></div>
            </div></div>`;
        }).join('') || '<div class="empty">沒有符合條件的卡片。</div>'}</div>`;

      app.querySelector('.toolbar').addEventListener('click', (e) => {
        const b = e.target.closest('button'); if (!b) return;
        if (b.dataset.deck) ui.deck = b.dataset.deck;
        else if (b.dataset.course) ui.course = b.dataset.course;
        else if (b.dataset.toggle) ui[b.dataset.toggle] = !ui[b.dataset.toggle];
        else if (b.dataset.reset) { const s2 = cardState(); D.cards.filter(c => c.deck === ui.deck).forEach(c => delete s2[cardKey(c)]); store.set('study.cards', s2); }
        store.set('study.cards.ui', ui); render();
      });
      app.querySelector('.deck-grid').addEventListener('click', (e) => {
        const fc = e.target.closest('.fc'); if (!fc) return;
        const card = cards[+fc.dataset.i];
        const mark = e.target.closest('button[data-mark]');
        if (mark) {
          e.stopPropagation();
          setCard(cardKey(card), mark.dataset.mark);
          fc.classList.remove('known', 'unknown'); fc.classList.add(mark.dataset.mark);
          fc.querySelector('.hint').textContent = mark.dataset.mark === 'known' ? '已熟' : '還不熟';
          setTimeout(() => fc.classList.remove('flipped'), 150);
          return;
        }
        fc.classList.toggle('flipped');
      });
    }
    render();
  }

  // ------------------------------------------------------------------ views: glossary
  function viewGlossary() {
    setActiveNav('glossary');
    app.innerHTML = `
      <h1>術語表</h1>
      <p class="lead">從七份導讀中「<strong>專有名詞</strong>（中文解釋）」的寫法自動抽出，共 ${D.glossary.length} 條。</p>
      <input class="search" id="gsearch" type="search" placeholder="搜尋術語或解釋…" autocomplete="off">
      <div class="gloss" id="glist"></div>`;
    const list = document.getElementById('glist');
    const draw = (q) => {
      q = (q || '').trim().toLowerCase();
      const rows = D.glossary.filter(g => !q || g.term.toLowerCase().includes(q) || g.def.toLowerCase().includes(q));
      list.innerHTML = rows.map(g => `<div class="row"><div><div class="term">${esc(g.term)}</div><div class="tags">${g.courses.map(courseChip).join('')}</div></div><div>${g.def}</div></div>`).join('') || '<div class="empty">沒有符合的術語。</div>';
    };
    document.getElementById('gsearch').addEventListener('input', (e) => draw(e.target.value));
    draw('');
  }

  // ------------------------------------------------------------------ router
  function route() {
    const hash = location.hash || '#/';
    const [path, anchor] = hash.slice(1).split('#');
    const parts = path.split('/').filter(Boolean);
    window.scrollTo(0, 0);
    if (parts[0] === 'course' && parts[1]) {
      viewCourse(parts[1]);
      if (anchor) { const el = document.getElementById(anchor); if (el) { const det = el.closest('.unit') || el; if (det.tagName === 'DETAILS') det.open = true; el.scrollIntoView({ block: 'start' }); } }
    } else if (parts[0] === 'core') viewCore(parts[1]);
    else if (parts[0] === 'cards') viewCards();
    else if (parts[0] === 'glossary') viewGlossary();
    else viewHome();
  }
  window.addEventListener('hashchange', route);

  document.getElementById('theme-toggle').addEventListener('click', () => {
    const cur = document.documentElement.dataset.theme;
    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
    const next = cur ? (cur === 'dark' ? 'light' : 'dark') : (prefersDark ? 'light' : 'dark');
    document.documentElement.dataset.theme = next;
    store.set('study.theme', next);
  });

  route();
})();
